import { Textarea } from "@/components/ui/textarea"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { SelectValue, SelectTrigger, SelectItem, SelectContent, Select } from "@/components/ui/select"
import Link from "next/link"
import { Download, PlayIcon, Volume2, VolumeX } from "lucide-react"
import { useState } from "react"
import { Voice, VoiceResponse } from "@/types"
import _ from "lodash"
import { useCreateAudioBuffer } from "@/app/queries/useCreateAudioBuffer"
import CONSTANTS from "@/app/config/constants"
import { PlayButton } from "./ui/playButton"
import { PageTarget } from "./server/mainForm"
import { Slider } from "./ui/slider"

type Props = {
  voices: Voice
  allVoices: VoiceResponse[]
  target: PageTarget
}

export function VoicemailGreetingComponent({ voices, allVoices, target }: Props) {
  console.log("VoicemailGreetingComponent initialized with data:", {
    voicesCount: Object.keys(voices).length,
    allVoicesCount: allVoices.length,
    availableAccents: allVoices.map((v) => v.labels.accent),
    availableVoices: allVoices.map((v) => ({ id: v.voice_id, name: v.name })),
  })
  const [isPlaying, setIsPlaying] = useState(false)
  const [text, setText] = useState(
    target === PageTarget.MAIN
      ? "Thank you for calling. I apologize for missing your call. I'm busy right now, but if you leave your name, number, and message, I will return your call as soon as possible."
      : `Thank you for calling. We appreciate your patience as we try to answer each call as quickly as possible
⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛
Thank you for holding, all our lines are currently busy. We apologize for the delay and will be with you shortly.
⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛
Thank you for your patience, please stay on the line while we direct your call to the next available representative
⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛⌛`,
  )
  const [audio, setAudio] = useState<HTMLAudioElement>()
  const [music, setMusic] = useState<string>("popular-corporate-upbeat")

  // Check if we have any American accent, otherwise use the first available accent
  const availableAccents = Array.from(new Set(allVoices.map((voice) => voice.labels.accent)))
  const initialAccent = availableAccents.includes("American") ? "American" : availableAccents.length > 0 ? availableAccents[0] : "American"

  const [accent, setAccent] = useState<string>(initialAccent)
  const [voiceVolume, setVoiceVolume] = useState<number>(100)
  const [bgVolume, setBgVolume] = useState<number>(30)

  // Default to first available voice with the selected accent, or any voice if none match
  const getDefaultVoice = () => {
    const voiceWithAccent = allVoices.find((v) => v.labels.accent === accent)
    return voiceWithAccent?.voice_id || (allVoices.length > 0 ? allVoices[0].voice_id : "")
  }

  // Use voice_id instead of name
  const [selectedVoice, setVoice] = useState<string>(getDefaultVoice())

  // Set a proper name for display, with a fallback if the voice isn't found
  const selectedVoiceName = allVoices.find((v) => v.voice_id === selectedVoice)?.name || "Select Voice"

  // Filter voices by selected accent
  const filteredVoices = allVoices.filter((voice) => voice.labels.accent === accent)

  // If no voices match the selected accent, show all voices
  const displayedVoices = filteredVoices.length > 0 ? filteredVoices : allVoices

  const mutation = useCreateAudioBuffer(text, selectedVoice, music)

  const handlePlay = () => {
    if (isPlaying) {
      console.log(audio)
      audio?.pause()
      setIsPlaying(false)
      return
    }

    window.dataLayer = window.dataLayer || []
    // Publish to GA Event with the selected voice & text and text

    window.dataLayer.push({
      event: "play_voicemail_greeting",
      event_category: "search",
      search_term: text,
    })

    window.dataLayer.push({
      event: "select_content",
      content_type: "voice",
      item_id: selectedVoice,
    })

    // Pass the voice and background volumes to the mutation
    mutation.mutation
      .mutateAsync({
        voiceVolume: voiceVolume / 100,
        bgVolume: bgVolume / 100,
        outputFormat: "wav", // Use WAV for streaming as it's faster to process
      })
      .then(async (d) => {
        const buffer = await d.blob()
        console.log(buffer)
        const url = URL.createObjectURL(buffer)
        const newAudio = new Audio(url)

        setAudio(newAudio)
        newAudio.onended = () => {
          setIsPlaying(false)
        }
        newAudio.onplay = () => {
          setIsPlaying(true)
        }

        newAudio.onloadedmetadata = () => {
          newAudio.play()
        }
      })
  }

  const download = () => {
    mutation.mutation
      .mutateAsync({
        voiceVolume: voiceVolume / 100,
        bgVolume: bgVolume / 100,
        outputFormat: "mp3",
      })
      .then(async (d) => {
        const buffer = await d.blob()
        const url = URL.createObjectURL(buffer)
        const a = document.createElement("a")
        a.href = url
        a.download = "VoicemailGreeting.mp3"
        a.click()
      })
  }

  return (
    <div className="max-w-2xl mx-auto p-4 bg-white rounded-lg shadow-md">
      <div className="mb-6">
        <Textarea
          className={`w-full ${
            target === PageTarget.MAIN ? "h-44" : "h-64"
          }  text-ellipsis leading-6 text-base  resize-none  p-4 rounded-lg  border-gray-500 focus:border-gray-300 focus:ring-2 focus:ring-gray-200 focus:ring-opacity-50 border-2`}
          onChange={(e) => setText(e.target.value)}
          value={text}
        />
        <div className="flex justify-end mt-4">
          <PlayButton isPlaying={isPlaying} isLoading={mutation.mutation.isPending} onClick={handlePlay} />
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 border-t border-b py-4">
        <div>
          <Label htmlFor="accent">Accent</Label>
          <Select
            value={accent}
            onValueChange={(value) => {
              setAccent(value)
              // When accent changes, set voice to first voice with that accent
              const firstVoiceWithAccent = allVoices.find((v) => v.labels.accent === value)
              if (firstVoiceWithAccent) {
                console.log("Changing to first voice of new accent:", firstVoiceWithAccent.name, firstVoiceWithAccent.voice_id)
                setVoice(firstVoiceWithAccent.voice_id)
              }
            }}>
            <SelectTrigger>
              <SelectValue>{accent.replace(/-/g, " ").replace(/\b\w/g, (char) => char.toUpperCase())}</SelectValue>
            </SelectTrigger>
            <SelectContent>
              {availableAccents.map((accentOption) => (
                <SelectItem key={accentOption} value={accentOption}>
                  {accentOption.replace(/-/g, " ").replace(/\b\w/g, (char) => char.toUpperCase())}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label htmlFor="voice">Voice</Label>
          <Select value={selectedVoice} onValueChange={setVoice}>
            <SelectTrigger>
              <SelectValue>{selectedVoiceName}</SelectValue>
            </SelectTrigger>
            <SelectContent>
              {displayedVoices.map((voice) => (
                <SelectItem key={voice.voice_id} value={voice.voice_id}>
                  {voice.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 py-4">
        <div>
          <Label htmlFor="category">Category</Label>
          <Select>
            <SelectTrigger>
              <SelectValue placeholder="Corporate" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="Corporate">Corporate</SelectItem>
              <SelectItem value="Narrative">Narrative</SelectItem>
              <SelectItem value="Commercial">Commercial</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label htmlFor="music">Music</Label>
          <Select value={music} onValueChange={setMusic}>
            <SelectTrigger>
              <SelectValue placeholder="Popular corporate upbeat" />
            </SelectTrigger>
            <SelectContent>
              {CONSTANTS.BG_MUSIC.map((music) => (
                <SelectItem key={music.text} value={music.file}>
                  {music.text}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Volume Controls */}
      <div className="border-t border-b py-4">
        <div className="mb-4">
          <div className="flex items-center justify-between mb-2">
            <Label className="flex items-center">
              <Volume2 className="w-4 h-4 mr-2" />
              Voice Volume
            </Label>
            <span className="text-sm text-gray-500">{voiceVolume}%</span>
          </div>
          <Slider defaultValue={[voiceVolume]} max={100} step={1} onValueChange={(value: number[]) => setVoiceVolume(value[0])} />
        </div>
        <div>
          <div className="flex items-center justify-between mb-2">
            <Label className="flex items-center">
              <Volume2 className="w-4 h-4 mr-2" />
              Background Music
            </Label>
            <span className="text-sm text-gray-500">{bgVolume}%</span>
          </div>
          <Slider defaultValue={[bgVolume]} max={100} step={1} onValueChange={(value: number[]) => setBgVolume(value[0])} />
        </div>
      </div>

      <div className="flex items-center justify-between py-4">
        <PlayButton isPlaying={isPlaying} isLoading={mutation.mutation.isPending} onClick={handlePlay} />

        <div className="flex items-center">
          {/* Download button */}
          <Button variant="link" onClick={download}>
            <Download className="mr-2" />
            Download
          </Button>
        </div>
      </div>
      <Link className="text-sm text-gray-500 underline" href="#">
        Edit text
      </Link>
    </div>
  )
}

export function PauseIcon(props: any) {
  return (
    <svg {...props} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="14" y="4" width="4" height="16" rx="1" />
      <rect x="6" y="4" width="4" height="16" rx="1" />
    </svg>
  )
}
